import { test, expect } from '@playwright/test';
import { signIn, book, freshLab } from '../e2e/helpers.js';

// Starter: ONE smoke test — it only checks that the app opens. It kills no mutant.
// Write the real tests below (see the task). Khởi đầu: MỘT test khói — chỉ kiểm app mở được, không diệt đột biến nào.
test('starter: the app opens', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('body')).toBeVisible();
});

// Code Lab · tst-cl-7-2 — LOCAL mutation grader (máy chấm đột biến chạy TRÊN MÁY BẠN).
// Run it inside your labflow-lite project folder:  node cham-tai-may.mjs [test files…]
// (default: the test file(s) of this exercise). Needs the Playwright browsers (npx playwright install) and port 4173 free — Playwright builds the web app and starts the e2e server itself.
// What it does — same algorithm as the course's mutation labs: your tests must be GREEN on the correct code, then each
// planted bug is written into its file one at a time (the file is ALWAYS restored, even on Ctrl+C) and your tests must
// turn RED; harmless changes must keep them GREEN. It prints N/N when every check passes.
import { readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

const DE = {
  "id": "tst-cl-7-2",
  "runner": "playwright",
  "config": null,
  "args": null,
  "tests": [
    "demo7/th72.spec.js"
  ],
  "dotBien": [
    {
      "file": "web/app/App.jsx",
      "from": "localStorage.setItem(KEY, JSON.stringify(next));",
      "to": "",
      "label": "the session is never saved (a reload signs you out)"
    },
    {
      "file": "web/BookingForm.jsx",
      "from": "'Booked. See you in ' + res.data.lab + '.'",
      "to": "'Booked. See you soon.'",
      "label": "the confirmation no longer says which lab"
    },
    {
      "file": "web/AdminBookings.jsx",
      "from": "<td>{b.start}–{b.end}</td>",
      "to": "<td>{b.start}</td>",
      "label": "the admin list loses the end time"
    },
    {
      "file": "web/AdminBookings.jsx",
      "from": "<td>{b.status}</td>",
      "to": "<td></td>",
      "label": "the admin cannot see whether a booking is confirmed"
    },
    {
      "file": "src/rules/booking.js",
      "from": "if (role === 'LECTURER' || role === 'ADMIN') return false;",
      "to": "if (role === 'ADMIN') return false;",
      "label": "a lecturer's 40-seat booking waits for approval"
    },
    {
      "file": "src/booking/service.js",
      "from": "return [...rows];",
      "to": "return [];",
      "label": "the admin list is always empty"
    }
  ],
  "voHai": [
    {
      "file": "web/app/App.jsx",
      "from": "const KEY = 'labflow.session';",
      "to": "const KEY = 'labflow.session.v2';",
      "label": "refactor: the session is stored under a new key (storageState is saved again by setup)"
    }
  ]
};

const tests = process.argv.slice(2).length ? process.argv.slice(2) : DE.tests;
const npx = (args) => spawnSync('npx', args, { encoding: 'utf8', shell: process.platform === 'win32' });
const run = () => (DE.runner === 'playwright'
  ? npx(['playwright', 'test', ...tests, ...(DE.args ?? ['--project=chromium'])])
  : npx(['vitest', 'run', ...(DE.config ? ['--config', DE.config] : []), ...tests, ...(DE.args ?? [])])).status;

let dangSua = null; // { file, goc } — trả lại nếu bị ngắt giữa chừng
const traLai = () => { if (dangSua) { writeFileSync(dangSua.file, dangSua.goc); dangSua = null; } };
process.on('SIGINT', () => { traLai(); process.exit(130); });

function voi(m, fn) {
  const goc = readFileSync(m.file, 'utf8');
  const n = goc.split(m.from).length - 1;
  if (n !== 1) {
    console.log(`  ? "${m.label}": the text to change was found ${n} times in ${m.file} — your file differs from the course version; copy ${m.file} from this exercise's starter and run again`);
    return null;
  }
  dangSua = { file: m.file, goc };
  writeFileSync(m.file, goc.replace(m.from, () => m.to));
  try { return fn(); } finally { traLai(); }
}

console.log(`${DE.id}: ${tests.join(' ')} (${DE.runner})`);
if (run() !== 0) {
  console.log('✘ Your tests are NOT green on the correct code — fix them first (the code has no bug). 0/' + (DE.dotBien.length + DE.voHai.length));
  process.exit(1);
}
console.log('✔ green on the correct code');
let dat = 0;
for (const m of DE.dotBien) {
  const st = voi(m, run);
  if (st != null && st !== 0) dat++;
  console.log(`${st == null ? '?' : st !== 0 ? '✔ killed   ' : '✘ SURVIVED '} ${m.label}`);
}
for (const m of DE.voHai) {
  const st = voi(m, run);
  if (st === 0) dat++;
  console.log(`${st == null ? '?' : st === 0 ? '✔ still green ' : '✘ RED (brittle)'} harmless: ${m.label}`);
}
const tong = DE.dotBien.length + DE.voHai.length;
console.log(`\n${dat}/${tong} ${dat === tong ? '— all mutants killed. Mark the exercise solved on the website.' : '— not yet.'}`);
process.exitCode = dat === tong ? 0 : 1;

// Helpers shared by the end-to-end tests (Chapter 7).
import { createHash } from 'node:crypto';

export const PASSWORD = 'labflow-demo';

export async function signIn(page, username) {
  await page.goto('/');
  await page.getByLabel('Username', { exact: true }).fill(username);
  await page.getByLabel('Password', { exact: true }).fill(PASSWORD);
  await page.getByRole('button', { name: 'Sign in' }).click();
}

export async function book(page, { lab = 'BE-201', date = '2026-11-16', start = '08:00', end = '10:00', seats = '20' } = {}) {
  await page.getByLabel('Lab', { exact: true }).fill(lab);
  await page.getByLabel('Date', { exact: true }).fill(date);
  await page.getByLabel('Start', { exact: true }).fill(start);
  await page.getByLabel('End', { exact: true }).fill(end);
  await page.getByLabel('Seats', { exact: true }).fill(seats);
  await page.getByRole('button', { name: 'Book' }).click();
}

// A lab code of its own for every test, every repeat and every retry: tests running in parallel never share a slot (lesson 7.3).
// Lesson 11.3: "QA-100…999" was only 900 codes — 25 tests had a 28% chance that two of them share one (the birthday problem),
// and renaming a test changed its testId, its code, and made an old test flaky. Two letters × 900 numbers = 608,400 codes.
const SPACE = 26 * 26 * 900;
export function freshLab(testInfo) {
  const key = [testInfo.testId, testInfo.repeatEachIndex, testInfo.retry].join('/');
  const n = parseInt(createHash('sha256').update(key).digest('hex').slice(0, 12), 16) % SPACE;
  const letters = String.fromCharCode(65 + Math.floor(n / 900 / 26), 65 + (Math.floor(n / 900) % 26));
  const lab = letters + '-' + String(100 + (n % 900));
  testInfo.annotations.push({ type: 'lab', description: lab });   // lesson 11.3: the report says which lab each test used
  return lab;
}

import { checkSlot, needsApproval } from '../rules/booking.js';

export class BookingError extends Error {
  constructor(code, options) {
    super(code, options);
    this.name = 'BookingError';
    this.code = code;
  }
}

// An in-memory "database" whose methods are async, like a real one.
export function createMemoryRepo() {
  const rows = [];
  const latency = () => new Promise((resolve) => setTimeout(resolve, 5));
  return {
    async findOverlap(lab, date, start, end) {
      await latency();
      return rows.find((b) => b.status !== 'CANCELLED' && b.lab === lab && b.date === date && b.start < end && start < b.end) ?? null; // a cancelled booking frees its slot (Chapter 11)
    },
    async insert(booking) {
      await latency();
      const row = { id: rows.length + 1, ...booking };
      rows.push(row);
      return row;
    },
    async findById(id) {
      await latency();
      return rows.find((b) => b.id === id) ?? null;
    },
    async list() {
      await latency();
      return [...rows];
    },
    async remove(id) { // Chapter 10: cancelling deletes the row and returns it (null if there was none)
      await latency();
      const i = rows.findIndex((b) => b.id === id);
      return i === -1 ? null : rows.splice(i, 1)[0];
    },
    count: () => rows.length,
    async listByUser(userId) { // Chapter 11: My bookings — one student's bookings, by date and start
      await latency();
      return rows.filter((b) => b.userId === userId).sort((a, b) => (a.date + a.start).localeCompare(b.date + b.start)).map((b) => ({ ...b }));
    },
    async cancel(id) { // Chapter 11: CONFIRMED or PENDING → CANCELLED in one step; null if missing or already cancelled
      await latency();
      const row = rows.find((b) => b.id === id && b.status !== 'CANCELLED');
      if (!row) return null;
      row.status = 'CANCELLED';
      return { ...row };
    },
  };
}

export async function bookLab(repo, input) {
  const slot = checkSlot(input.start, input.end);
  if (!slot.ok) throw new BookingError(slot.code);
  let clash;
  try {
    clash = await repo.findOverlap(input.lab, input.date, input.start, input.end);
  } catch (err) {
    throw new BookingError('STORAGE_DOWN', { cause: err });
  }
  if (clash) throw new BookingError('OVERLAP');
  const status = needsApproval(input) ? 'PENDING' : 'CONFIRMED';
  try {
    return await repo.insert({ ...input, minutes: slot.minutes, status });
  } catch (err) {
    if (err instanceof BookingError) throw err; // Chapter 4: the database itself can say OVERLAP
    throw new BookingError('STORAGE_DOWN', { cause: err });
  }
}

import { parseTime } from './time.js';

export const OPEN = 7 * 60;          // 07:00
export const CLOSE = 21 * 60;        // 21:00
export const STEP = 30;              // BR-04: 30-minute grid
export const MAX_MINUTES = 240;      // Lite-1: at most 4 hours
export const MAX_DAYS_AHEAD = 14;    // BR-05: at most 14 days ahead
export const APPROVAL_SEATS = 30;    // BR-06: more than 30 seats needs approval

export function checkSlot(start, end) {
  const s = parseTime(start);
  const e = parseTime(end);
  if (s % STEP !== 0 || e % STEP !== 0) return { ok: false, code: 'OFF_GRID' };
  if (e <= s) return { ok: false, code: 'END_BEFORE_START' };
  if (s < OPEN || e > CLOSE) return { ok: false, code: 'OUTSIDE_HOURS' };
  if (e - s > MAX_MINUTES) return { ok: false, code: 'TOO_LONG' };
  return { ok: true, minutes: e - s };
}

export function isWithinBookingWindow(daysAhead) {
  return Number.isInteger(daysAhead) && daysAhead >= 0 && daysAhead <= MAX_DAYS_AHEAD;
}

export function needsApproval({ seats, role }) {
  if (!Number.isInteger(seats) || seats < 1) {
    throw new RangeError('seats must be a positive integer, got ' + seats);
  }
  if (role === 'LECTURER' || role === 'ADMIN') return false;
  return seats > APPROVAL_SEATS;
}

export function createBooking({ lab, seats, role, start, end }) {
  const slot = checkSlot(start, end);
  if (!slot.ok) throw new Error(slot.code);
  return {
    lab,
    start,
    end,
    minutes: slot.minutes,
    status: needsApproval({ seats, role }) ? 'PENDING' : 'CONFIRMED',
  };
}

// Share of opening hours already booked, added booking by booking (0..1).
export function usageRate(bookings) {
  let rate = 0;
  for (const b of bookings) rate += b.minutes / (CLOSE - OPEN);
  return rate;
}

'use client';
// The admin list: one screen, four states — loading, forbidden or failed, empty, and the table.
import { useCallback, useEffect, useState } from 'react';

export function AdminBookings({ client }) {
  const [state, setState] = useState({ phase: 'loading' });

  const load = useCallback(async () => {
    setState({ phase: 'loading' });
    try {
      const res = await client.listAll();
      if (res.status === 403) setState({ phase: 'forbidden' });
      else if (res.status !== 200) setState({ phase: 'failed' });
      else setState({ phase: 'done', bookings: res.data });
    } catch {
      setState({ phase: 'failed' });
    }
  }, [client]);

  useEffect(() => { load(); }, [load]);

  if (state.phase === 'loading') return <p role="status">Loading bookings…</p>;
  if (state.phase === 'forbidden') return <p role="alert">Only admins can see all bookings.</p>;
  if (state.phase === 'failed') {
    return (
      <div role="alert">
        <p>Could not load the bookings.</p>
        <button type="button" onClick={load}>Try again</button>
      </div>
    );
  }
  if (state.bookings.length === 0) return <p>No bookings yet.</p>;
  return (
    <table aria-label="All bookings">
      <thead><tr><th>Lab</th><th>Date</th><th>Time</th><th>Seats</th><th>Status</th></tr></thead>
      <tbody>
        {state.bookings.map((b) => (
          <tr key={b.id}><td>{b.lab}</td><td>{b.date}</td><td>{b.start}–{b.end}</td><td>{b.seats}</td><td>{b.status}</td></tr>
        ))}
      </tbody>
    </table>
  );
}

// The LabFlow Lite web app (Chapter 7): sign in, then book a lab — or, as an admin, see every booking.
import { useState } from 'react';
import { createClient } from '../api.js';
import { BookingForm } from '../BookingForm.jsx';
import { AdminBookings } from '../AdminBookings.jsx';
import { MyBookings } from '../MyBookings.jsx';
import { LoginForm } from './LoginForm.jsx';

const KEY = 'labflow.session';

function loadSession() {
  try { return JSON.parse(localStorage.getItem(KEY)); } catch { return null; }
}

// Chapter 11: a student has two pages — book a lab (/) and My bookings (/my-bookings). Plain links: no router needed.
function StudentPages({ client }) {
  const mine = window.location.pathname === '/my-bookings';
  return (
    <>
      <nav aria-label="Pages">
        <a href="/" aria-current={mine ? undefined : 'page'}>Book a lab</a> · <a href="/my-bookings" aria-current={mine ? 'page' : undefined}>My bookings</a>
      </nav>
      {mine
        ? (<><h2>My bookings</h2><MyBookings client={client} /></>)
        : (<><h2>Book a lab</h2><BookingForm onSubmit={client.createBooking} /></>)}
    </>
  );
}

export function App() {
  const [session, setSession] = useState(loadSession);

  function signIn(next) {
    localStorage.setItem(KEY, JSON.stringify(next));
    setSession(next);
  }
  function signOut() {
    localStorage.removeItem(KEY);
    setSession(null);
  }

  if (!session) {
    return (<><header><h1>LabFlow Lite</h1></header><main><LoginForm onLogin={signIn} /></main></>);
  }
  const client = createClient({ token: session.token });
  return (
    <>
      <header>
        <h1>LabFlow Lite</h1>
        <span>Signed in as {session.user.id} ({session.user.role}) <button type="button" onClick={signOut}>Sign out</button></span>
      </header>
      <main>
        {session.user.role === 'ADMIN'
          ? (<><h2>All bookings</h2><AdminBookings client={client} /></>)
          : (<StudentPages client={client} />)}
      </main>
    </>
  );
}

'use client';
// The booking form. It checks what it can in the browser, then shows what the API answered.
import { useState } from 'react';

export const MESSAGES = {
  OFF_GRID: 'Times must be on the half hour (08:00, 08:30 …).',
  END_BEFORE_START: 'The end time must be after the start time.',
  OUTSIDE_HOURS: 'Labs are open from 07:00 to 21:00.',
  TOO_LONG: 'A booking can last at most 4 hours.',
  OVERLAP: 'This slot is already taken. Choose another time.',
};

export function validate(input) {
  const errors = {};
  if (!/^[A-Z]{2}-\d{3}$/.test(input.lab)) errors.lab = 'A lab code looks like BE-201.';
  if (!input.date) errors.date = 'Choose a date.';
  if (!input.start) errors.start = 'Choose a start time.';
  if (!input.end) errors.end = 'Choose an end time.';
  if (!Number.isInteger(input.seats) || input.seats < 1 || input.seats > 200) errors.seats = 'Seats must be a whole number from 1 to 200.';
  return errors;
}

function Field({ name, label, error, ...input }) {
  const id = 'booking-' + name;
  return (
    <p>
      <label htmlFor={id}>{label}</label>
      <input id={id} name={name} aria-invalid={error ? 'true' : undefined} aria-describedby={error ? id + '-error' : undefined} {...input} />
      {error && <span id={id + '-error'}>{error}</span>}
    </p>
  );
}

export function BookingForm({ onSubmit }) {
  const [errors, setErrors] = useState({});
  const [result, setResult] = useState(null);
  const [busy, setBusy] = useState(false);

  async function handleSubmit(event) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const input = {
      lab: form.get('lab'), date: form.get('date'), start: form.get('start'), end: form.get('end'),
      seats: Number(form.get('seats')),
    };
    const found = validate(input);
    setErrors(found);
    setResult(null);
    if (Object.keys(found).length > 0) return;
    setBusy(true);
    try {
      const res = await onSubmit(input);
      if (res.status === 201) {
        const text = res.data.status === 'PENDING' ? 'Sent. A lecturer must approve this booking.' : 'Booked. See you in ' + res.data.lab + '.';
        setResult({ ok: true, text });
      } else if (res.status === 400) {
        setErrors(Object.fromEntries(res.data.error.details.map((d) => [d.path, d.message])));
      } else {
        setResult({ ok: false, text: MESSAGES[res.data.error.code] ?? 'Something went wrong. Try again.' });
      }
    } catch {
      setResult({ ok: false, text: 'Cannot reach the server. Check your connection.' });
    } finally {
      setBusy(false);
    }
  }

  return (
    <form aria-label="Book a lab" noValidate onSubmit={handleSubmit}>
      <Field name="lab" label="Lab" error={errors.lab} defaultValue="BE-201" />
      <Field name="date" label="Date" type="date" error={errors.date} />
      <Field name="start" label="Start" type="time" error={errors.start} />
      <Field name="end" label="End" type="time" error={errors.end} />
      <Field name="seats" label="Seats" type="number" error={errors.seats} />
      <button type="submit" disabled={busy}>{busy ? 'Booking…' : 'Book'}</button>
      {result && <p role={result.ok ? 'status' : 'alert'}>{result.text}</p>}
    </form>
  );
}

